import numpy as np
import re

def parse_amount(val):
    if val is None:
        return np.nan
    if not isinstance(val, str):
        val = str(val)
    # Rule 1: Trim spaces
    s = val.strip()
    # Rule 2: Treat empty values as NaN
    if s == "" or s.lower() == "nan":
        return np.nan

    # Rule 3: Treat the value as negative if:
    # - it contains "CR" (case sensitive? Usually yes or case insensitive? Let's check if there are other cases. "C1 118.59 CR" -> contains "CR". Let's do "CR" in s.)
    # - it is enclosed in parentheses
    # - it contains a minus sign "-"
    is_negative = False
    if "CR" in s:
        is_negative = True
    if s.startswith("(") and s.endswith(")"):
        is_negative = True
    if "-" in s:
        is_negative = True

    # Rule 4: Remove tokens (e.g., C1, C2) and keep only digits, commas, and periods
    s = re.sub(r"[^\d.,]", "", s)

    # Rule 5: Treat empty strings or strings with nothing left as NaN
    if s == "":
        return np.nan

    # Rule 6: Handle separators and determine if they are decimals or thousands
    # ... (Implementation of separator logic will be done here)
    decimal_separator = None
    thousands_separator = None
    if "," in s and "." in s:
        # If both separators exist, last one is the decimal
        if s.rfind(",") > s.rfind("."):
            decimal_separator = ","
            thousands_separator = "."
        else:
            decimal_separator = "."
            thousands_separator = ","
    elif "," in s:
        # If only commas, last one is decimal if exactly two digits follow
        if s.count(",") > 0:
            last_comma_index = s.rfind(",")
            if len(s[last_comma_index + 1:]) == 2:
                decimal_separator = ","
            else:
                thousands_separator = ","
    elif "." in s:
        # If only periods, last one is decimal if exactly two digits follow
        if s.count(".") > 0:
            last_period_index = s.rfind(".")
            if len(s[last_period_index + 1:]) == 2:
                decimal_separator = "."
            else:
                thousands_separator = "."

    # ... (Complete processing based on identified separators, and return the numerical value)

    if decimal_separator is None and thousands_separator is None:
        try:
            return float(s)
        except ValueError:
            return np.nan # If no separators, just try to parse

    # Remove thousand separators
    if thousands_separator:
        s = s.replace(thousands_separator, "")

    # Replace decimal separator with "." for parsing
    if decimal_separator:
        s = s.replace(decimal_separator, ".")

    try:
        amount = float(s)
        if is_negative:
            amount = -amount
        return amount
    except ValueError:
        return np.nan
